export function number(value,label='Score'){if(value==null||typeof value==='boolean'||String(value).trim()==='')throw Error(`${label} is required.`);const n=Number(value);if(!Number.isFinite(n))throw Error(`${label} must be finite.`);return n;}
export function rawScore(value,label='Raw score'){const n=number(value,label);if(n<0||n>100)throw Error(`${label} must be between 0 and 100.`);return n;}
export function logistic(raw,p){return p[0]/(1+p[1]*Math.exp(-p[2]*raw));}
export function scale(model,subject,raw){const c=model.subjects[subject];if(!c)throw Error(`Subject not found: ${subject}`);const v=logistic(rawScore(raw),c.parameters);if(!Number.isFinite(v)||v<0||v>100)throw Error(`The fitted curve for ${subject} gives a score outside 0–100 at raw ${raw}. No prediction was produced.`);return v;}
function roundEven(x){const n=Math.floor(x),f=x-n;return f===.5?(n%2===0?n:n+1):Math.round(x);}
export function atarFromAggregate(score){number(score);let a;if(score>=480)a=.105689*score+48.1028;else if(score>=460)a=.159404*score+22.2647;else if(score>=440)a=.184285*score+10.7144;else if(score>=400)a=.179784*score+12.6542;else if(score>=350)a=.176741*score+13.8199;else if(score>=300)a=.199207*score+5.79687;else a=.299062*score-23.4011;a=Number((roundEven(a/.05)*.05).toFixed(2));return a<30?0:Math.min(99.95,a);}
export function predict(model,entries){if(entries.length<5)throw Error('Enter at least five distinct subjects before predicting an ATAR.');const seen=new Set();const rows=entries.map(({subject,raw})=>{if(seen.has(subject))throw Error(`Duplicate subject: ${subject}`);seen.add(subject);return {subject,raw:rawScore(raw),scaled:scale(model,subject,raw)};});const best=[...rows].sort((a,b)=>b.scaled-a.scaled).slice(0,5),aggregate=best.reduce((s,r)=>s+r.scaled,0);return {rows:rows.map(r=>({...r,counted:best.includes(r)})),aggregate,atar:atarFromAggregate(aggregate)};}
export function compare(model,subject,raw){const scaled=scale(model,subject,raw);return {scaled,rows:Object.entries(model.subjects).sort(([a],[b])=>a.localeCompare(b)).map(([name,c])=>{const [L,a,b]=c.parameters,value=-Math.log((L-scaled)/(a*scaled))/b;return {subject:name,raw:Number.isFinite(value)&&value>=0&&value<=100?value:null};})};}
const missing=v=>v==null||String(v).trim()==='';
function first(row,cols,label){for(const c of cols)if(!missing(row[c]))return rawScore(row[c],`${label}: ${c}`);throw Error(`${label}: supply ${cols.join(' or ')}.`);}
export function batchPredict(model,data,conversions,adjust){if(!data.length)throw Error('The Data sheet is empty.');if(adjust&&!conversions?.length)throw Error('Mock adjustment needs a non-empty MEAConversions sheet with Subject, m and c.');const conv=new Map();if(adjust)for(const row of conversions){const subject=String(row.Subject??'').trim();if(!subject)throw Error('Every conversion needs a Subject.');if(conv.has(subject))throw Error(`Duplicate conversion: ${subject}`);conv.set(subject,{m:number(row.m,`${subject} m`),c:number(row.c,`${subject} c`)});}
const students=new Map(),breakdown=[],unadjusted=new Set();data.forEach((row,i)=>{const name=String(row.Name??'').trim(),subject=String(row.Subject??'').trim(),label=`Row ${i+2}`;if(!name||!subject)throw Error(`${label}: Name and Subject are required.`);let ea=first(row,['MEA','FEA'],label);const originalEA=ea;if(adjust){if(conv.has(subject)){const c=conv.get(subject);ea=Math.min(50,c.c+c.m*ea);if(ea<0)throw Error(`${label}: adjusted external score is negative.`);}else unadjusted.add(subject);}const raw=first(row,['IA1','FIA1'],label)+first(row,['IA2','FIA2'],label)+first(row,['IA3','FIA3'],label)+ea;rawScore(raw,`${label}: total`);if(!students.has(name))students.set(name,[]);students.get(name).push({subject,raw});breakdown.push({Name:name,Subject:subject,Raw:raw,Scaled:scale(model,subject,raw),'Original external':originalEA,'Used external':ea,'Mock adjusted':adjust&&conv.has(subject)?'Yes':'No'});});
const results=[];for(const [name,entries]of students){let r;try{r=predict(model,entries);}catch(e){throw Error(`${name}: ${e.message}`);}results.push({Name:name,Aggregate:r.aggregate,ATAR:r.atar});for(const row of breakdown.filter(r=>r.Name===name))row['Counted in best five']=r.rows.find(r=>r.subject===row.Subject).counted?'Yes':'No';}return {results:results.sort((a,b)=>b.ATAR-a.ATAR),breakdown,warnings:unadjusted.size?[`No conversion for ${[...unadjusted].join(', ')}; their external scores were left unchanged.`]:[]};}
